-- =============================================
-- 실제 기출 시드: (1)형 → 2017년 1회
-- points(배점) 컬럼 + quiz_answers AI 채점 컬럼 추가 + 문제 시드
-- Supabase SQL Editor에서 실행하세요
-- =============================================

ALTER TABLE public.questions ADD COLUMN IF NOT EXISTS points int NOT NULL DEFAULT 0;
ALTER TABLE public.quiz_answers ADD COLUMN IF NOT EXISTS ai_score int;
ALTER TABLE public.quiz_answers ADD COLUMN IF NOT EXISTS ai_feedback jsonb;

-- 기존 동일 시험 회차 정리(재실행 대비)
DELETE FROM public.questions WHERE year = 2017 AND round = 1;

INSERT INTO public.questions (year, round, number, type, points, passage, question, options, correct_answer, explanation) VALUES
(2017, 1, 7, 'essay', 50, '시민사회와 전문가가 정부의 화학물질 감시 파트너가 될 수 있다. … 정책의 중심에는 안전과 생명이 있어야 한다. … 생활화학제품이 무해한 것처럼 광고하는 행위를 규제해 제품 오남용을 방지해야 한다. … 화학물질이 제품에 어떤 용도로 쓰이는지에 따른 위해성 평가가 철저히 이뤄져야 한다. … 피해를 관리할 수 있는 중독센터를 만들어야 한다.', '김○○ 부장은 화학물질의 안전한 관리를 위한 정책 발표 프레젠테이션을 작성하고 있다. 제시문을 사용하여 ㉠~㉣에 들어갈 문장을 조건에 맞게 쓰시오.

【조건】
1. ㉠~㉣은 글의 문단 순서대로 쓸 것.
2. ''~해야 한다.''로 종결하고 3~8어절로 쓸 것.', NULL, '㉠ 사람(안전과 생명) 중심의 정책을 수립해야 한다.
㉡ 허위·과장 광고를 규제해야 한다.
㉢ 제품에 쓰이는 화학물질의 위해성 평가를 철저히 해야 한다.
㉣ 중독센터를 만들어야 한다.', '5가지 제언 중 시민사회 협력을 제외한 나머지를 문단 순서대로 ''~해야 한다.'' 형식으로 정리한다.'),
(2017, 1, 8, 'essay', 100, '(가) 부장님, 이대로는 적정 이윤을 낼 수 없습니다. 납품 단가 조정이 필요합니다. (주)■■기업이 발주해 생산 중인 ○○제품의 가공임 거래 계약이 벌써 3년 전입니다. 특히 요즘 인력 부족으로 인건비가 급격히 상승해서 종전의 단가로는 납품하기가 정말 힘듭니다.', '다음 (가)를 보고 (나) 공문서의 빈칸에 들어갈 내용을 조건에 따라 두 문단으로 서술하시오.

【조건】
1. 첫 번째 문단은 ''귀사에서 발주하여''로 시작하되, (가)를 참고하여 ''기존의 계약과 변화된 상황''을 각각 한 문장으로 쓸 것.
2. 두 번째 문단은 ''이에 따라''로 시작하되 (가)를 참고하여 ''제안 내용과 붙임 내용 언급, 양해를 바라는 표현''을 총 두 문장으로 쓸 것.', NULL, '귀사에서 발주하여 생산 중인 ○○제품의 가공임 거래 계약이 3년 전에 약정하여 오늘에 이르고 있습니다. 그러나 최근 인력 부족으로 인해 인건비가 급격히 상승하였으며, 종전의 단가로는 적정 이윤을 맞출 수 없는 상황에 이르고 말았습니다.
이에 따라 귀사에서 발주할 제품의 납품 단가를 조정하여 생산하고자 합니다. 첨부된 새로운 단가표를 검토해 주시기 바라며, 당사의 입장을 양해해 주시기 바랍니다.', '공문서의 격식(경어·간결성)을 지키고 조건의 시작 어구·문장 수를 정확히 맞춘다.'),
(2017, 1, 9, 'essay', 100, '<현재 상황> 직원의 창의적 발상이 중요함 / 업무량 과중으로 문화 체험 기회 없음 / 기획력 향상 방안 필요. <제안> 월 1회 뮤지컬 관람의 날 지정. <효과> 피로감 해소 / 상상력·기획력 제고 / 친밀도·팀워크 향상.', '김○○ 대리는 ''뮤지컬 관람의 날 지정'' 제안서를 쓰려 한다. 빈칸 ㉠~㉢에 들어갈 내용을 조건에 맞게 작성하시오.

【조건】
1. ㉠에 문서의 성격을 나타낼 제목을 쓸 것. (5어절 이내)
2. ㉡에 제안 이유를 회사 특성·현재 상황과 관련지어 제시할 것.
3. ㉢에 제안 효과를 2문장으로 쓸 것.', NULL, '㉠ ''뮤지컬 관람의 날'' 지정 제안서
㉡ 우리 회사는 업무 특성상 직원의 창의적인 발상이 가장 중요하지만, 업무량이 과중하여 다양한 문화를 체험할 기회가 전혀 없는 실정입니다. 이에 직원의 기획력을 향상할 방안으로 다음과 같은 제안서를 제출합니다.
㉢ 과중한 업무로 인한 피로감을 해소하고 문화 행사를 직접 체험함으로써 상상력과 기획력을 높일 수 있습니다. 또한 전 직원이 함께 참여함으로써 친밀도가 향상되어 조직의 팀워크도 높일 수 있습니다.', '제안서의 형식과 조건(제목 어절 수, 문장 수)을 지키고 회사 상황과 효과를 구체적으로 연결한다.'),
(2017, 1, 10, 'essay', 200, '(가) NCS 직무 기술서: 생산관리 엔지니어 / 직무 수행 태도 — 전체 공정에 대한 통찰적 사고, 책임감. (나) 직무 기술서: 화학공학 공정설계 경진대회 장려상(팀장).', '직무 능력 소개서의 ''3. 경험 기술서''를 <개요>를 바탕으로 작성하시오.

【조건】
1. 네 문단으로 서술할 것. (800자 내외)
2. (가)·(나)의 내용 일부를 활용하되 각 문단의 주어진 문장 수를 지킬 것.
3. 불필요한 내용을 서술할 경우 감점함.

<개요>
1문단(2~3문장): 경진대회 과제 / 아세트산 생산 설비 설계 / 4인 1팀 / 장려상
2문단(5~6문장): 원인 분석 — 최우수상 팀은 전체적 시각, 우리는 세부 설계 집중 / 전체 공정 못 살핌 / 팀장 책임
3문단(4~5문장): 소설 『제3인류』 / 나무와 숲 / 서적·논문으로 통찰력 / 일에 큰 힘
4문단(3~4문장): 학부 지식 활용 / 더 배울 것 / 창의적 응용으로 최고가 될 것', NULL, '3학년 여름방학을 전국 화학공학 공정설계 경진대회 과제를 해결하며 보냈습니다. 아세트산 생산 설비를 설계하라는 과제를 4명이 한 팀이 되어 해결했지만, 아쉽게 장려상에 그쳤습니다.
원인을 알아보기 위해 대상·최우수상 팀과 저희 보고서를 비교했습니다. 두 팀은 공정을 전체적인 시각에서 분석했으나, 저희는 열역학방정식·증류탑 등 세부 설계에 집중한 나머지 전체 공정을 살피지 못했습니다. 전체 맥락에서 설계하지 못했음을 깨달았고, 팀장으로서 큰 책임을 느꼈습니다.
베르나르 베르베르는 『제3인류』에서 한 곳에 지나치게 집중하면 전체를 놓친다고 했습니다. 나무와 숲을 함께 보려는 노력이 필요합니다. 이후 공정설계 관련 서적과 논문을 읽으며 통찰력을 길렀고, 이는 생산관리 엔지니어로 일하는 데 큰 힘이 될 것입니다.
직무를 수행하며 학부에서 배운 지식을 최대한 활용하고, 더 많은 것을 새롭게 익히겠습니다. 습득한 지식을 창의적으로 응용하여 최고의 생산관리 엔지니어가 되겠습니다.', '개요의 문단별 문장 수를 지키고, 경험-교훈-적용의 흐름을 800자 내외로 구성한다.'),
(2017, 1, 11, 'multiple', 8, NULL, '위 상황에서 신입사원 최○○ 씨가 컨설팅 업무 계약 취소 통 보를 받게 된 이유를 적절하게 쓴 것은?', '["사업 제안서 필수 항목을 빠뜨리고 썼기 때문이다.","제안서의 내용을 충분하게 쓰지 못했기 때문이다.","인간관계를 고려하지 않고 딱딱한 문체로 썼기 때문이다.","다른 회사의 제안서와 달리 신입사원의 신분으로 썼기 때문 이다.","공식적인 이메일에 공과 사를 구분하지 못하는 내용을 썼기 때문이다."]'::jsonb, '5', ''),
(2017, 1, 12, 'multiple', 8, NULL, '문서를 작성하던 김○○ 사원은 읽기에 따라 불필요한 말이 반복되거나 중의적으로 해석할 여지가 있는 문장을 가려내어 고쳤다. 다음 중 적절하게 고친 문장은?', '["그는 나보다 회사 일을 더 우선한다.","그 문제는 다시 재고해 볼 필요가 있습니다.","성실한 그의 상사는 항상 일찍 출근하여 사무실 청소를 한다.","일정한 액수 이하를 송금할 때는 수수료를 내지 않아도 됩니다.","올바른 사회를 만들기 위해서는 사회악을 뿌리 뽑아 근절해 야 한다. 1교시 3 15"]'::jsonb, '4', ''),
(2017, 1, 15, 'multiple', 8, NULL, '다음 중 신입사원에게 배포할 공문서 작성법으로 적절하지 않 은 것은?', '["전달력이 높은 공적인 언어를 씁니다.","경어체 ‘-합니다.’, ‘-입니다.’, ‘-습니다.’를 씁니다.","문학적 표현보다는 논리적 표현과 공적인 용어 위주로 씁니다.","일상용어보다 정확한 의미전달을 위해 어려운 한자어를 주로 씁니다.","실용문에 적합한 용어로 핵심을 전달하는 구체적 실사 위주의 문장을 씁니다."]'::jsonb, '4', ''),
(2017, 1, 18, 'multiple', 8, NULL, '위와 같은 채용공고문에 따른 입사지원서의 특성으로 적절하 지 않은 것은?', '["직무기반 입사지원서: 해당 직무를 성공적으로 수행할 가능성이 높은 지원자를 선별하기 위한 것으로 해당 기업, 기관의 모집 분 야별 직무수행에 필요한 내용을 기재할 수 있도록 구성되어 있다.","인적사항: 개별 지원자를 식별하고 관리하기 위한 성명, 생년 월일, 연락처 등 최소한의 정보로만 구성되어 있다.","교육사항: 직무 수행에 필요한 지식, 기술, 태도를 갖추고 있 는가를 평가하기 위한 항목으로 크게 학교 교육과 직업교육으 로 구성되어 직무에 대한 지원자의 관심과 노력을 판단하는 척도로 활용된다.","자격사항: NCS 세부 분류별로 제시된 자격현황을 참고하여 지원자가 직무수행에 필요한 기술을 가졌는지 판단할 수 있도 록, 취득한 자격은 모두 기록하도록 한다.","경력 사항 및 직무 관련 활동: 지원자가 직무와 관련된 일이 나 경험 여부를 평가하기 위한 항목으로 경력기술서, 경험기술 서, 자기소개서에 구체적으로 작성하도록 하여 면접 시 참고자 료로 활용한다."]'::jsonb, '4', ''),
(2017, 1, 20, 'multiple', 8, NULL, '위 품의서에 첨부할 내용으로 적절하지 않은 것은?', '["견적서","타사 비교 견적서","복합기 임대차 계약서","총무팀 업무량 증가 추이","실용디에스 사업자 관련 서류"]'::jsonb, '4', ''),
(2017, 1, 21, 'multiple', 8, NULL, '위와 같은 글을 작성하는 요령에 대한 설명으로 가장 적절한 것은?', '["기술을 담보로 투자를 유치하여 투자 회사와 이익을 공유하 기 위해 작성한다.","주요 의사 결정 사항에 대한 담당자 및 실행 기한 등 향후 계획을 구체적으로 기술한다.","문제 해결 요건을 충족하고 상대방의 공감과 흥미를 불러일 으켜 해당 안이 채택될 수 있도록 쓴다.","작성자의 이해관계 및 선입견을 배제하고 과거 사례 및 타부 서의 의견 등을 포괄적으로 검토하여 작성한다.","기업이 제공 또는 창출할 수 있는 제품 및 서비스 등을 제시 하고 이를 실현하기 위한 구체적인 방법과 운영 계획 등을 소 개한다. 1교시 5 15"]'::jsonb, '3', ''),
(2017, 1, 23, 'multiple', 8, NULL, '위 광고를 제작하기 전에 작성한 광고 기획서에 광고의 제작 배경으로 제시할 수 있는 자료로 적절한 것은?', '["고령 친화제품 기술 개발 계획","1970년~2015년까지의 출산율 변화 추이","고령사회 성장동력 확보를 위한 근로자 직업 훈련","저출산 대책사업의 일환인 무상보육료 및 차등보육료","고령화에 대한 각종 연금, 보험, 노인 복지사업비 내역"]'::jsonb, '2', ''),
(2017, 1, 24, 'multiple', 8, NULL, '위 광고에 대한 부가적인 광고 문구를 쓰려고 한다. 다음 중 적절하지 않은 것은?', '["OECD 국가 중 최저 출산율의 나라","세계에서 고령화가 가장 빨리 진행 중인 나라","아이보다 어른이 많은 나라, 상상해 보셨나요?","내 아이를 갖는 기쁨과 나라의 미래를 함께 생각해 주세요.","아이 교육에 대한 투자, 스마트한 생활, ○○폰으로 함께 해요."]'::jsonb, '5', ''),
(2017, 1, 25, 'multiple', 8, NULL, '다음 중 기안문서에 관해 쓴 문장으로 가장 적절한 것은?', '["내용과 관련된 다른 부서의 협조를 얻기 위해 작성한 문서이 다.","접수 문서를 배포 절차에 따라 담당 업무 처리과로 배포한 문서이다.","결재 문서, 결재권자의 결재를 얻기 위해 서식에 따라 작성한 문서이다.","발송문서, 기안 내용을 실행하기 위해 규정된 서식으로 작성 한 문서이다.","외부로부터 받은 문서를 접수 담당 부서에서 절차를 거쳐 접 수한 문서이다."]'::jsonb, '3', ''),
(2017, 1, 29, 'multiple', 8, NULL, '위와 같은 글을 쓸 때의 유의 사항으로 적절하지 않은 것은?', '["될 수 있으면 전문용어를 피하고 짧은 문장으로 작성한다.","사전지식이나 정보가 부족한 사람의 입장에서 쉽고 짧게 쓴다.","수식어는 빼고 전달하고자 하는 핵심만을 간결하고 명쾌하게 적는다.","반드시 완결되었거나 주어진 자료로 예측 가능한 내용을 가 지고 작성한다.","구체적이고 감각적인 어휘를 사용하여 실질적이고 유용한 정 보를 제공한다."]'::jsonb, '5', ''),
(2017, 1, 33, 'multiple', 8, NULL, '위 연수 자료의 검토를 부탁받은 기술혁신팀 김○○ 대리는 ‘필요한 자질과 능력’을 역할별로 추가하여 쓰는 것이 좋다고 말하였다. 역할별로 필요한 자질과 능력을 바르게 쓴 것은?', '["아이디어 창안: 아이디어의 응용에 관심","챔피언: 업무 수행 방법에 대한 지식","프로젝트 관리: 혁신적인 빠른 진행","정보 수문장: 원만한 대인 관계 능력","후원: 새로운 분야의 일을 즐김"]'::jsonb, '4', ''),
(2017, 1, 35, 'multiple', 8, NULL, '김○○ 사원의 사내 메신저 글을 읽고 정○○ 대리는 김○○ 사원에게 ‘건조한 날씨에 따른 주의사항 	‘1~4.’ 항을 좀 더 자 세한 내용으로 제품 사용 설명서를 써서 세단기에 부착하라고 지시하였다. 자세한 제품 사용 설명서를 쓸 때 그 내용으로 가 장 적절한 것은?', '["옷 끼임 주의: 세단기에 따라 정해진 세단 매수를 지켜주세요.","어린이 접근 금지: 세단 매수 초과 시 세단기의 수명이 짧아 집니다.","전기 조심: 어린이의 사용은 위험합니다. 감전 및 화상 등 부 상의 위험이 있습니다.","세단 매수 준수: 많은 세단 매수를 한 번에 세단할 수 있는 강력한 모터를 가지고 있습니다.","전기 조심: 물이 묻은 손으로 전원 플러그를 만지지 마세요. 감전 및 고장의 우려가 있습니다."]'::jsonb, '5', ''),
(2017, 1, 38, 'multiple', 8, NULL, '다음 사례에서 파악할 수 있는 갈등의 단서에 관해 쓴 것은? 필기도구를 생산하는 ○○ 회사가 부도 위기에 처했다. 이 에 따라 ○○ 회사는 부서를 합리화시키고 원가를 절약할 방 법을 찾고자 특별 대책반을 만들었다. 반장인 갑은 반원들에 게 원가절감 방안에 대해 자유롭게 의견을 제시하라고 하였 다. 을은 다음과 같은 제안을 했다. “제가 생각하기에는 재고 를 줄이는 것이 추가비용을 절감하는 길입니다.”라고 말하자, 병이 “잠깐만요.”라고 말하며 을의 말을 가로막았다. “현 상 황에서 재고를 줄일 수는 없습니다. 그건 말도 안 되는 소리 예요.”라고 병이 다소 큰 목소리로 말하였다.', '["차분하게 논평과 제안을 한다.","편을 가르고 타협하기를 거부한다.","핵심을 이해하지 못한 데 대해 서로 비난한다.","타인의 의견발표가 끝나기도 전에 그 의견에 대해 공격한다.","개인적인 감정을 내세우면서 미묘한 말투와 방식으로 서로를 공격한다."]'::jsonb, '4', ''),
(2017, 1, 39, 'multiple', 8, NULL, '다음과 같은 업무수행 시트에 대한 설명을 가장 적절하게 쓴 것은?', '["평가 기준을 명확히 하는 일이 중요하다.","일의 흐름을 동적으로 보여주는 데 효과적이다.","여러 가지 기준에 대해 질문하고 현황을 파악하여 업무 수행 을 점검하거나 평가한다.","단계별로 업무를 시작해서 끝나는 데 걸리는 시간을 막대 형 식으로 표시할 때 사용한다.","업무를 세부적인 활동으로 나누고 각 활동별로 기대되는 수 행 수준을 달성하였는지 확인할 수 있다."]'::jsonb, '2', ''),
(2017, 1, 43, 'multiple', 8, NULL, '예산책정에 어려움을 겪고 있는 박○○ 대리에게 전임자가 쓴 메시지 중 적절하지 않은 것은?', '["개발책정비용과 실제 비용은 비슷하게 맞추는 것이 가장 이 상적이에요.","우선순위가 높은 활동부터 적절하게 예산을 배정하고 예산을 사용하세요.","예산 지출 규모를 확인하고 예산을 우선 책정해야 하는 항목 을 도출하는 것이 좋아요.","처음에는 업무를 추진하는 과정에서 예산이 필요한 모든 활 동을 도출하는 것이 필요해요.","배정된 예산으로 모든 업무를 수행할 수 있도록 예산액을 필 요한 곳에 적절히 증감 할당하는 것이 필요해요."]'::jsonb, '5', ''),
(2017, 1, 46, 'multiple', 8, NULL, '서술된 직무 내용을 참고하여 이어질 내용을 가장 적절하게 쓴 것은? 출근하면 각종 업무 관련 정보를 웹사이트를 통하여 확인하 고, 각 본부, 팀별 현안 및 이슈에 대한 이메일 확인과 피드 백, 전자결재 합의 등의 업무를 수행한다. 또한, 주요 일간지 와 주간지 기사 검색, 각종 정보제공 사이트를 보면서 경제 동향, 산업 동향, 국외투자 동향 등 전반적인 사업영역과 관 련된 시장 및 경쟁사 동향 등을 점검하고 정리하기도 한다. 본격적인 업무가 시작되는 9시부터는 제반 문제를 해결하기 위한 업무 미팅, 회사 내 각종 회의체 참여 업무를 수행한다. 또한, ( 	)', '["회사의 사무공간과 각종 물품의 공급 및 관리를 총괄한다.","국외 법인의 매출 손익 분석 등을 통해 중장기 전략을 수립 하는 일도 한다.","영업현황 및 판매지표를 관리하고, 시장 환경 분석을 통한 마 케팅전략을 수립한다.","의전 및 비서업무, 집기 비품 및 소모품의 구매와 관리, 국내 외 출장 업무 협조 요청을 한다.","인사정책의 방향과 전략을 기획하고 직무분석을 통한 부서별 인력산정, 적정 인력의 배치와 평가를 한다. 1교시 11 15"]'::jsonb, '2', '');
